// Compiled only into the netstandard2.1 build. The project removes this file from
// every other target, the way dotnet/runtime conditions its own polyfills.
//
// This file holds only the framework APIs netstandard2.1 lacks that this project
// calls. The compiler-required types (IsExternalInit and
// CallerArgumentExpressionAttribute) are generated by PolySharp; see
// Directory.Build.props.
//
// The namespace is Hyperbee.Pipeline, not the Internal folder's. A C# 14 static
// extension member is only a candidate where its containing type is in scope, and
// Hyperbee.Pipeline is in scope for every Hyperbee.Pipeline.* namespace. The type
// is internal, so each assembly's copy is visible to that assembly alone.

#nullable enable

namespace Hyperbee.Pipeline;

/// <summary>
/// Stands in for the static <c>ArgumentNullException.ThrowIfNull</c> added in .NET 6.
/// </summary>
internal static class CachingNetstandardShims
{
    extension( ArgumentNullException )
    {
        public static void ThrowIfNull( object? argument, [System.Runtime.CompilerServices.CallerArgumentExpression( nameof( argument ) )] string? paramName = null )
        {
            if ( argument is null )
                throw new ArgumentNullException( paramName );
        }
    }
}
